import type { BunRouter, BunResponse } from "@kingsleyweb/bun-common";
import { createCache, memoryDriver } from "@kingsleyweb/bun-cache";
const cache = createCache({ driver: memoryDriver() });
const pages = m.cacheResponse(cache, { ttl: 60_000, varyBy: ["accept-language"], tags: (req) => [req.originalUrl] });
export type _pagesNotAny = Expect<IsAny<typeof pages>>;
export type _invalidate = Equal<ReturnType<typeof pages.invalidate>, Promise<void>>;
declare const router: BunRouter;
router.get("/posts/:id", pages, (_req, res) => { res.send("ok"); });
router.use("/feed", m.coalesceRequests({ wait: 5_000 }));
declare const res: BunResponse;
m.addCacheTags(res, "post:1");
export const _status: t.CacheStatus = "HIT";
export const _options: t.CacheResponseOptions = { ttl: "headers", honorRequest: true, coalesce: { wait: 1_000 } };

export type _fetchNotAny = Expect<IsAny<typeof m.default.fetch>>;
export const _answer: Promise<Response> = m.default.fetch(new Request("https://bun-cache.example.workers.dev/storage/kv/namespaces/CACHE_KV/keys"), { BUN_CACHE_PROXY_TOKEN: "secret", CACHE_KV: {} });
const env: t.BunCacheWorkerEnv = { BUN_CACHE_PROXY_TOKEN: "secret" };
export type _envSecret = Equal<typeof env.BUN_CACHE_PROXY_TOKEN, string | undefined>;
